    $ch1Story = "सृष्टि के आरम्भ में जब देवताओं और असुरों ने मिलकर समुद्र-मंथन किया, तब अनेक रत्न प्रकट हुए। उन्हीं में से एक थे — श्रीगणेशजी, जो विघ्नहर्ता और सर्वप्रथम पूज्य हैं। भगवान शिव और माता पार्वती ने उन्हें अपने पुत्र के रूप में स्वीकार किया। ब्रह्माजी ने उन्हें ऋद्धि और सिद्धि — दो दिव्य शक्तियों के साथ विवाह कराया। ऋद्धि और सिद्धि साक्षात लक्ष्मी के अंश थीं।\n\nएक दिन की बात है। श्रीगणेशजी कैलाश पर्वत पर अपनी दोनों पत्नियों — ऋद्धि और सिद्धि के साथ विराजमान थे। उनके मुख पर एक अजीब-सी चिन्ता की छाया थी। ऋद्धि ने पूछा —\n\n“स्वामी! आज आपके मुख पर उदासी क्यों है? क्या कोई चिन्ता है?”\n\nश्रीगणेशजी ने गम्भीर स्वर में कहा —\n\n“प्रिये! मैं अपने भक्तों की दशा देखकर व्याकुल हूँ। संसार में अनेक प्राणी हैं जो सुख-सुविधा होने पर भी असंतोष से ग्रस्त हैं। उनके मन में शान्ति नहीं है। मैं चाहता हूँ कि ऐसी एक देवी प्रकट हों जो संतोष और समृद्धि की देवी बनें। जो अपने भक्तों के हृदय में सन्तोष भर दें।”\n\nयह कहकर श्रीगणेशजी ने अपनी दिव्य शक्ति से एक तेजस्वी प्रकाश उत्पन्न किया। उस प्रकाश से एक अद्भुत देवी प्रकट हुईं। उनका रूप ऐसा था मानो स्वयं लक्ष्मी ने जन्म लिया हो। उनके मुख पर सन्तोष और शान्ति की अद्भुत आभा थी। उनके हाथों में वरद-मुद्रा और अभय-मुद्रा थी। उनके मुकुट से दिव्य रत्न चमक रहे थे।\n\nऋद्धि और सिद्धि ने आश्चर्य से पूछा —\n\n“स्वामी! यह दिव्य कन्या कौन है? इसका तेज तो सूर्य को भी लज्जित कर रहा है।”\n\nश्रीगणेशजी ने मुस्कुराकर कहा —\n\n“यह मेरी ही पुत्री है। इसका नाम संतोषी है। यह सन्तोष की देवी होंगी। जो भी भक्त इनकी श्रद्धा से उपासना करेगा, उसके जीवन से असंतोष दूर हो जाएगा और सुख-शान्ति की प्राप्ति होगी।”\n\nसंतोषी माता ने अपने पिता श्रीगणेशजी को प्रणाम किया और हाथ जोड़कर कहा —\n\n“पिताजी! आपने मुझे इस संसार में भेजा है तो मुझे अपने भक्तों के लिए एक व्रत का विधान बताइए, जिससे वे मेरी कृपा प्राप्त कर सकें।”\n\nश्रीगणेशजी ने कहा —\n\n“पुत्रि! शुक्रवार का दिन तुम्हारी उपासना के लिए सर्वश्रेष्ठ होगा। जो स्त्री या पुरुष लगातार 16 शुक्रवार तक तुम्हारा व्रत करेगा और गुड़ एवं चने की दाल का भोग अर्पित करेगा, उसे तुम्हारी विशेष कृपा प्राप्त होगी। परन्तु व्रत के दिन खट्टी वस्तुएँ ग्रहण नहीं करनी चाहिए।”\n\nसंतोषी माता ने अपने पिता के वचन को स्वीकार किया और उसी दिन से शुक्रवार का व्रत प्रारम्भ हुआ।\n\nउधर पृथ्वी पर एक नगर में एक धर्मात्मा व्यापारी रहता था, जिसका नाम जिनदत्त था। वह बहुत धनी था, परन्तु उसके हृदय में भगवान के प्रति अपार श्रद्धा थी। उसकी पत्नी का नाम सुमंगला था। वे दोनों सन्तान-सुख से वंचित थे। बहुत समय तक उन्होंने संतान के लिए प्रार्थना की। अन्ततः माँ संतोषी की कृपा से उनके घर एक कन्या ने जन्म लिया, जिसका नाम उन्होंने सत्यवती रखा।\n\nसत्यवती बचपन से ही अत्यन्त सुन्दर, गुणवती और भगवान की भक्त थी। जब वह सोलह वर्ष की हुई, तो एक दिन उसकी माता सुमंगला ने उसे अपने पास बिठाया और कहा —\n\n“पुत्रि! आज मैं तुम्हें माँ संतोषी के व्रत का महात्म्य बताती हूँ। यह व्रत लगातार 16 शुक्रवार तक किया जाता है। इस व्रत में माँ संतोषी का पूजन किया जाता है और उन्हें गुड़ और चने की दाल का भोग लगाया जाता है। व्रत के दिन खट्टी वस्तु ग्रहण नहीं करनी चाहिए। जो स्त्री यह व्रत करती है, उसके जीवन से सारे दुख दूर हो जाते हैं और माँ संतोषी की कृपा प्राप्त होती है।”\n\nसत्यवती ने माता के मुख से व्रत का महात्म्य सुना तो उसका हृदय श्रद्धा से भर गया। उसने हाथ जोड़कर कहा —\n\n“माता! मैं यह व्रत अवश्य करूँगी। मैं माँ संतोषी की कृपा चाहती हूँ, जिससे मेरा जीवन सुखी और शान्तिपूर्ण हो।”\n\nसुमंगला ने कहा —\n\n“पुत्रि! यह व्रत श्रद्धा और भक्ति से करना। प्रत्येक शुक्रवार को स्नान करके पूजन करना, कथा सुनना और प्रसाद ग्रहण करना।”\n\nसत्यवती ने व्रत का संकल्प ले लिया। पहला शुक्रवार आया। उसने ब्रह्ममुहूर्त में स्नान किया, स्वच्छ वस्त्र पहने और माँ संतोषी की प्रतिमा के सम्मुख बैठी। उसने गणेशजी और माँ संतोषी का विधिवत पूजन किया। गुड़ और चने की दाल का भोग लगाया। फिर हाथ जोड़कर प्रार्थना की —\n\n“ॐ संतोषी मातायै नमः। हे माँ संतोषी! मुझे सन्तोष और सुख प्रदान करें। मेरे जीवन से सारे दुख दूर हों। मेरे हृदय में शान्ति का वास हो।”\n\nइस प्रकार सत्यवती ने 16 शुक्रवार का व्रत श्रद्धापूर्वक आरम्भ किया। प्रत्येक शुक्रवार को वह पूजन करती, कथा सुनती और प्रसाद ग्रहण करती। माँ संतोषी उसकी भक्ति से प्रसन्न थीं और उसके जीवन में सुख-शान्ति बनी रहती।\n\nपरन्तु सत्यवती के जीवन में एक परीक्षा आने वाली थी। उसके विवाह के बाद उसे अपने ससुराल जाना था। उसके पिता जिनदत्त ने एक योग्य वर देखकर उसका विवाह किया। वर का नाम था — सुन्दरदास। वह भी धर्मात्मा और सुशील था। विवाह के बाद सत्यवती अपने पति के घर गई। उसके पति का परिवार बड़ा था — सास, ससुर और दो ननदें। ननदों का स्वभाव कठोर था। वे सत्यवती से ईर्ष्या करती थीं, क्योंकि सत्यवती रूप में और गुणों में उनसे श्रेष्ठ थी।\n\nसत्यवती ने अपने ससुराल में भी संतोषी माता का व्रत करना जारी रखा। प्रत्येक शुक्रवार को वह पूजन करती और माँ संतोषी को गुड़-चने का भोग लगाती। परन्तु उसकी ननदें उसकी भक्ति और व्रत को देखकर जलती थीं। वे अपनी माता से कहतीं —\n\n“माता! हमारी भाभी तो जादू-टोना करती है। वह हर शुक्रवार को कुछ पूजा-पाठ करती है। कहीं वह हमारे परिवार पर कोई मन्त्र तो नहीं कर रही?”\n\nसास पहले तो शान्त रही, परन्तु धीरे-धीरे उसके मन में भी सन्देह पैदा हो गया।\n\nएक दिन ननदों ने मिलकर एक षड्यन्त्र रचा। उन्होंने सोचा — “हम एक ऐसा काम करेंगे जिससे भाभी का व्रत टूट जाए और उसे अपनी माँ की शक्ति का प्रमाण मिल जाए।”\n\nसत्यवती की भक्ति और ननदों की ईर्ष्या के बीच व्रत का 16वाँ शुक्रवार निकट आ रहा था। सत्यवती इस दिन का बड़ी प्रतीक्षा से इंतज़ार कर रही थी। उसने मन में संकल्प किया था कि 16वें शुक्रवार को उद्यापन करेगी और माँ संतोषी को गुड़-चने का भोग लगाकर प्रसाद बाँटेगी।\n\nपरन्तु वह नहीं जानती थी कि उसकी ननदें उसके व्रत को तोड़ने के लिए क्या षड्यन्त्र रच रही हैं।";

    $ch2Title = "ननदों का षड्यन्त्र और सत्यवती की परीक्षा";
    $ch2Story = "सत्यवती का व्रत और भक्ति दिन-प्रतिदिन बढ़ती जा रही थी। उसके घर में माँ संतोषी की कृपा से सुख-शान्ति बनी हुई थी। परन्तु उसकी दोनों ननदें — चन्द्रा और मुक्ता — इस सबको सहन नहीं कर पा रही थीं। वे देखतीं कि भाभी हर शुक्रवार को पूजा करती है, गुड़-चने का भोग लगाती है और घर में सब उसका आदर करते हैं। उनके हृदय में ईर्ष्या की आग जलने लगी।\n\nएक दिन दोनों ननदें आपस में बैठकर विचार करने लगीं —\n\n“बहन! देखो, हमारी भाभी कितनी धर्मात्मा बनती है। सारे घर में उसकी ही चर्चा है। माता भी उसकी बात मानने लगी हैं। हमें कुछ ऐसा करना चाहिए जिससे उसका यह व्रत टूट जाए और माता को पता चले कि वह कितनी झूठी है।”\n\nचन्द्रा ने कहा —\n\n“बहन! मैंने सुना है कि यह व्रत 16 शुक्रवार तक चलता है। अभी तो कुछ ही शुक्रवार बीते हैं। हमें ऐसा षड्यन्त्र रचना चाहिए कि उसका व्रत किसी भी प्रकार टूट जाए।”\n\nमुक्ता ने कहा —\n\n“हाँ! मैंने सुना है कि इस व्रत में खट्टी वस्तु नहीं खानी चाहिए और प्रसाद स्वयं नहीं खाना चाहिए, पहले देवी को अर्पित करना चाहिए। हम ऐसा कुछ करेंगे कि भाभी से कोई भूल हो जाए।”\n\nइस प्रकार दोनों ननदों ने मिलकर एक षड्यन्त्र रचा। उन्होंने सोचा —\n\n“हम एक शुक्रवार को भाभी के पूजा के समय उनका प्रसाद — गुड़ और चने की दाल — चुपचाप खा जाएँगे। फिर माता को बताएँगे कि भाभी ने स्वयं प्रसाद खा लिया और देवी को अर्पित नहीं किया। इससे माता क्रोधित होकर उसे दण्ड देंगी और उसका व्रत टूट जाएगा।”\n\nअगला शुक्रवार आया। सत्यवती ने प्रातः स्नान किया, स्वच्छ वस्त्र पहने और पूजा की तैयारी करने लगी। उसने गुड़ और चने की दाल को एक थाली में सजाया और देवी की प्रतिमा के सम्मुख रख दिया। फिर वह स्नान के लिए गई, क्योंकि पूजा से पहले उसे फिर से स्नान करना था।\n\nउसी समय चन्द्रा और मुक्ता ने अपना षड्यन्त्र कार्यान्वित किया। वे चुपचाप पूजा-स्थल पर आईं और वह थाली उठाकर ले गईं। उन्होंने वह सारा गुड़-चना खा लिया और खाली थाली वहीं छोड़ दी। फिर वे अपनी माता के पास गईं और रोने का नाटक करने लगीं —\n\n“माता! माता! देखिए, भाभी ने क्या किया! उसने देवी को प्रसाद अर्पित करने से पहले ही सारा गुड़-चना स्वयं खा लिया। हमने देखा तो वह हमें धमकाने लगी कि किसी को मत बताना।”\n\nसास ने आश्चर्य से पूछा —\n\n“क्या? सत्यवती ने ऐसा किया? यह कैसे हो सकता है? वह तो सदा व्रत-पूजन करती है।”\n\nननदें बोलीं —\n\n“माता! वह सब दिखावा है। उसके हृदय में कोई भक्ति नहीं है। उसने केवल घर में अपना प्रभुत्व जमाने के लिए यह व्रत किया था। आप स्वयं जाकर देख लीजिए, थाली खाली पड़ी है।”\n\nसास ने जाकर देखा तो वास्तव में थाली खाली थी। उसका मन भी सन्देह से भर गया। उसने सोचा — “क्या सत्यवती ने वास्तव में ऐसा किया? यदि हाँ, तो यह तो देवी का अपमान है।”\n\nइसी बीच सत्यवती स्नान करके लौटी। उसने देखा कि उसकी पूजा की थाली खाली पड़ी है और माँ क्रोध से उसकी ओर देख रही हैं। वह हाथ जोड़कर बोली —\n\n“माता! यह क्या हुआ? मेरा प्रसाद कहाँ गया? मैंने तो इसे अभी यहीं रखा था।”\n\nसास ने कठोर स्वर में कहा —\n\n“सत्यवती! तू यह दिखावा मत कर। तूने स्वयं ही प्रसाद खा लिया और अब झूठ बोल रही है कि तुझे नहीं पता। क्या तुझे यह भी नहीं पता कि व्रत का प्रसाद पहले देवी को अर्पित करना चाहिए? तूने यह कैसा व्रत किया है?”\n\nसत्यवती की आँखों में आँसू आ गए। उसने हाथ जोड़कर कहा —\n\n“माता! मैंने कुछ नहीं खाया। मैंने तो प्रसाद देवी को अर्पित करने के लिए रखा था। मुझे नहीं पता कि यह कैसे हुआ। मैं सत्य बोल रही हूँ।”\n\nपरन्तु सास का मन ननदों के कारण भर गया था। उसने सत्यवती को डाँटा और कहा —\n\n“चुप रह! तू झूठी है। तेरे कारण हमारे घर की इज्जत मिट्टी में मिल रही है। तू जा, इस घर से निकल जा।”\n\nसत्यवती ने अपने पति सुन्दरदास की ओर देखा। वह भी माँ के क्रोध को देखकर चुप था। उसे नहीं पता था कि सत्य बोल रही है या झूठ। उसने कहा —\n\n“सत्यवती! तुम कुछ दिनों के लिए अपने पिता के घर चली जाओ। जब यह बात शान्त हो जाए, तब मैं तुम्हें लेने आऊँगा।”\n\nसत्यवती का हृदय टूट गया। वह अपने कमरे में गई और रोने लगी। उसने माँ संतोषी को पुकारा —\n\n“माँ संतोषी! यह क्या हो गया? मैंने कभी किसी का बुरा नहीं किया। मैंने तो आपका व्रत श्रद्धा से किया। फिर यह दुख क्यों आया? क्या मेरी भक्ति में कोई कमी थी? माँ! मेरी सहायता करो। मुझे न्याय दो।”\n\nउसी रात, सत्यवती ने अपने थाली में गुड़-चना रखा और माँ संतोषी की प्रतिमा के सम्मुख बैठकर कहा —\n\n“माँ! मैं अपने व्रत का कोई अधूरा पालन नहीं करूँगी। मैं जानती हूँ कि मैं निर्दोष हूँ। आप मेरी सहायता करें।”\n\nउस रात सत्यवती ने जागरण किया और माँ संतोषी का ध्यान किया। उसके हृदय में विश्वास था कि माँ संतोषी उसकी रक्षा अवश्य करेंगी।\n\nउधर चन्द्रा और मुक्ता अपनी सफलता पर प्रसन्न थीं। उन्होंने सोचा — “अब भाभी घर से चली जाएगी और हम शान्ति से रहेंगी।” परन्तु वे यह नहीं जानती थीं कि माँ संतोषी अपने भक्तों की रक्षा कैसे करती हैं।\n\nअगली सुबह सत्यवती ने अपनी गठरी बाँधी और अपने पिता के घर की ओर चल पड़ी। रास्ते में वह माँ संतोषी का नाम जपती जा रही थी —\n\n“ॐ संतोषी मातायै नमः। जय संतोषी माता, जय जय संतोषी माता।”\n\nरास्ते में उसे एक मंदिर दिखाई दिया, जिसमें माँ संतोषी की प्रतिमा थी। वह मंदिर में गई और प्रतिमा के सम्मुख बैठ गई। उसने हाथ जोड़कर कहा —\n\n“माँ! मैं निर्दोष हूँ। मुझे इस घर से निकाल दिया गया। मेरे पति भी मेरा साथ नहीं दे रहे। माँ! अब आप ही मेरा सहारा हैं। मुझे न्याय दो। मेरे व्रत को सफल करो।”\n\nफिर वह वहीं बैठकर रोने लगी। उसकी आँखों से आँसुओं की धारा बह रही थी। उसने माँ संतोषी के चरणों में अपना सारा दुख अर्पित कर दिया।\n\nतभी आकाश में एक दिव्य प्रकाश फैल गया। मंदिर की दीवारें चमकने लगीं और एक मधुर वाणी सुनाई दी —\n\n“पुत्रि! सत्यवती! उठो! मैं तुम्हारी भक्ति से प्रसन्न हूँ। तुम्हारा व्रत अभी टूटा नहीं है। जो प्रसाद तुम्हारी ननदों ने खाया, वह तुम्हारे व्रत का फल नहीं है। तुमने तो मन से प्रसाद अर्पित किया था। तुम्हारा संकल्प सच्चा है। अब तुम वापस जाओ और अपने व्रत को पूर्ण करो। मैं तुम्हें न्याय दूँगी।”\n\nसत्यवती ने आश्चर्य से चारों ओर देखा। उसे एक दिव्य स्त्री का दर्शन हुआ — चार भुजाओं वाली, सिंहासन पर विराजमान, हाथों में वरद-मुद्रा और अभय-मुद्रा। वही माँ संतोषी थीं।\n\nसत्यवती ने हाथ जोड़कर कहा —\n\n“माँ! मैं आपकी शरण में हूँ। मुझे बताइए, मैं क्या करूँ?”\n\nमाँ संतोषी ने कहा —\n\n“पुत्रि! तुम अपने ससुराल लौट जाओ। अपना व्रत पूरा करो। 16वें शुक्रवार को उद्यापन करो। मैं तुम्हारी ननदों को उनकी करनी का फल अवश्य दूँगी। परन्तु तुम अपने हृदय में क्रोध न रखना। क्षमा ही सबसे बड़ा धर्म है।”\n\nयह कहकर माँ संतोषी अन्तर्धान हो गईं। सत्यवती के हृदय में नई शक्ति और विश्वास का संचार हुआ। वह मंदिर से बाहर आई और ससुराल की ओर लौट पड़ी।\n\nउधर ससुराल में माँ संतोषी की कृपा से एक अद्भुत घटना घटी। चन्द्रा और मुक्ता, जिन्होंने प्रसाद खाया था, उनके पेट में अचानक भयंकर पीड़ा होने लगी। वे दोनों छटपटाने लगीं और उन्हें उल्टियाँ होने लगीं। सास घबरा गई और वैद्य को बुलाया।\n\nवैद्य ने देखा और कहा —\n\n“इन्होंने कुछ ऐसा खाया है जो इनके पेट में विष बन गया है। यह कोई साधारण बीमारी नहीं है।”\n\nतभी सत्यवती घर पहुँची। उसने देखा कि ननदें पीड़ा से तड़प रही हैं और सास व्याकुल हैं। सत्यवती ने माँ संतोषी को याद किया और जल लेकर ननदों के मुख पर छिड़का। उसने कहा —\n\n“माँ संतोषी! इन्हें क्षमा कर दो। ये अज्ञानवश भूल कर बैठीं।”\n\nतभी चन्द्रा और मुक्ता को होश आया। उन्होंने रोते हुए सारी बात बताई —\n\n“माता! हमने ही भाभी के प्रसाद को खाया था। हमने ही उन पर झूठा आरोप लगाया। हमें क्षमा कर दो।”\n\nसास ने आश्चर्य से सत्यवती की ओर देखा। उसकी आँखों से आँसू बहने लगे। उसने सत्यवती के चरण पकड़ लिए —\n\n“पुत्रि! मुझे क्षमा कर। मैंने तुझे बिना सोचे-समझे दण्ड दिया। तू सच्ची है।”\n\nसत्यवती ने सास को उठाया और कहा —\n\n“माता! यह सब माँ संतोषी की माया है। अब कोई शोक नहीं। मैं अपना व्रत पूरा करूँगी और 16वें शुक्रवार को उद्यापन करूँगी।”\n\nउसी दिन से घर में फिर सुख-शान्ति लौट आई। सत्यवती ने अपना व्रत जारी रखा और माँ संतोषी की कृपा से उसका जीवन सुखी हो गया। परन्तु 16वें शुक्रवार के उद्यापन में एक और परीक्षा उसका इंतज़ार कर रही थी।";

    $ch3Title = "सोलहवाँ शुक्रवार, उद्यापन और अन्तिम परीक्षा";
    $ch3Story = "सत्यवती का व्रत अब अपने अन्तिम चरण में था। पन्द्रह शुक्रवार बीत चुके थे और सोलहवाँ शुक्रवार — उद्यापन का दिन — निकट आ रहा था। सत्यवती ने मन में संकल्प किया कि वह इस दिन विधिपूर्वक माँ संतोषी का उद्यापन करेगी, गुड़-चने का भोग लगाएगी और प्रसाद बाँटकर सभी का आशीर्वाद लेगी।\n\nसत्यवती ने अपनी सास से कहा —\n\n“माता! सोलहवाँ शुक्रवार आने वाला है। मैं माँ संतोषी का उद्यापन करना चाहती हूँ। कृपया इसके लिए आज्ञा दें और सामग्री एकत्र करने में सहायता करें।”\n\nसास ने प्रसन्न होकर कहा —\n\n“पुत्रि! तूने हमारे घर की इज्जत बचाई है। तेरी भक्ति से हम सब धन्य हैं। तू जो कहे, वही होगा। मैं स्वयं सारी सामग्री एकत्र करवाती हूँ।”\n\nसत्यवती ने सोलहवें शुक्रवार के लिए विशेष तैयारी की। उसने गुड़, चने की दाल, नारियल, केले, पुष्प, माला, रोली, अक्षत, दीपक और सुहाग सामग्री मँगवाई। उसने घर के आँगन को फूलों और रंगोली से सजाया। माँ संतोषी की प्रतिमा को नए वस्त्र पहनाए और उनका सिंहासन फूलों से सजाया।\n\nसोलहवें शुक्रवार की प्रातः सत्यवती ने ब्रह्ममुहूर्त में स्नान किया। उसने स्वच्छ वस्त्र पहने और माँ संतोषी के सम्मुख बैठकर संकल्प लिया —\n\n“ॐ संतोषी मातायै नमः। हे माँ! आज मैं अपने सोलहवें शुक्रवार का व्रत पूर्ण कर रही हूँ। मैंने जो भी भूल की हो, उसे क्षमा करें। मेरे व्रत को सफल करें। मेरे परिवार में सुख-शान्ति बनी रहे।”\n\nउसने गणेशजी और माँ संतोषी का विधिवत पूजन किया। गुड़ और चने की दाल का भोग लगाया। धूप, दीप, पुष्प और नैवेद्य अर्पित किए। फिर उसने कथा सुनी और आरती गाई।\n\nपूजन के बाद सत्यवती ने सास और अन्य स्त्रियों को प्रसाद बाँटा। उसने गुड़-चने का प्रसाद सभी को दिया और कहा —\n\n“यह माँ संतोषी का प्रसाद है। इसे श्रद्धा से ग्रहण करें।”\n\nपरन्तु जब प्रसाद बाँटने की बात आई, तो एक समस्या उत्पन्न हुई। उस दिन किसी कारणवश बाजार में चने की दाल समाप्त हो गई थी। सत्यवती के पास जितनी दाल थी, वह सब पूजन में लग गई थी और प्रसाद बाँटने के लिए कुछ शेष नहीं बचा था।\n\nसत्यवती चिन्तित हो गई। उसने सोचा —\n\n“माँ संतोषी! अब मैं क्या करूँ? प्रसाद बाँटना तो उद्यापन का अनिवार्य अंग है। यदि प्रसाद नहीं बाँटा, तो मेरा उद्यापन अधूरा रह जाएगा।”\n\nउसने अपनी सास से कहा —\n\n“माता! प्रसाद के लिए चने की दाल नहीं है। क्या आप किसी को बाजार भेज सकती हैं?”\n\nसास ने कहा —\n\n“पुत्रि! आज तो सारे बाजार में दाल ही नहीं है। क्या करें?”\n\nसत्यवती ने हाथ जोड़कर माँ संतोषी से प्रार्थना की —\n\n“माँ! आप सर्वशक्तिमान हैं। आप ही कोई उपाय करें। मेरा उद्यापन अधूरा न रहे।”\n\nउसी समय एक अद्भुत घटना घटी। सत्यवती के घर के द्वार पर एक साधु आया। उसने कहा —\n\n“माँ! मैं भूखा हूँ। मुझे कुछ भोजन दीजिए।”\n\nसत्यवती ने साधु को देखा। उसका हृदय करुणा से भर गया। उसने सोचा —\n\n“यदि मैं इस साधु को प्रसाद दे दूँ, तो यही मेरा उद्यापन का प्रसाद बाँटना हो जाएगा। माँ संतोषी की कृपा से कोई भी जीव प्रसाद के योग्य है।”\n\nउसने साधु को गुड़-चने का प्रसाद दिया और कहा —\n\n“बाबा! यह माँ संतोषी का प्रसाद है। इसे श्रद्धा से ग्रहण करें।”\n\nसाधु ने प्रसाद ग्रहण किया और मुस्कुराकर कहा —\n\n“पुत्रि! तेरा उद्यापन सफल हो। माँ संतोषी तुझ पर प्रसन्न हैं।”\n\nयह कहकर साधु अन्तर्धान हो गया। सत्यवती ने आश्चर्य से देखा — वह साधु कोई और नहीं, स्वयं भगवान श्रीगणेश थे, जो अपनी पुत्री माँ संतोषी की कृपा से उसकी परीक्षा लेने आए थे।\n\nसत्यवती का उद्यापन सफल हुआ। उसने माँ संतोषी को प्रणाम किया और उनकी कृपा से उसका जीवन सुखमय हो गया।\n\nपरन्तु उसी रात सत्यवती को स्वप्न में माँ संतोषी ने दर्शन दिए और कहा —\n\n“पुत्रि! तूने मेरा व्रत पूर्ण किया। तेरी भक्ति से मैं प्रसन्न हूँ। परन्तु अभी एक और परीक्षा शेष है। कल तेरे पति तुझे लेने आएँगे, परन्तु रास्ते में उन्हें एक विपत्ति आएगी। तुझे उनकी रक्षा करनी होगी।”\n\nसत्यवती ने स्वप्न में पूछा —\n\n“माँ! मेरे पति को क्या विपत्ति आएगी? मैं कैसे उनकी रक्षा करूँ?”\n\nमाँ संतोषी ने कहा —\n\n“पुत्रि! जब वे वन के रास्ते से आ रहे होंगे, तब एक भयंकर साँप उन्हें डसने वाला होगा। तू उस समय मेरा नाम जपना और उनकी रक्षा करना। मेरी कृपा से वह साँप उन्हें हानि नहीं पहुँचा सकेगा।”\n\nसत्यवती ने स्वप्न में हाथ जोड़कर कहा —\n\n“माँ! मैं ऐसा ही करूँगी।”\n\nप्रातःकाल सत्यवती ने सारी बात अपनी सास को बताई। सास ने कहा —\n\n“पुत्रि! माँ संतोषी की कृपा तुझ पर है। तू निर्भय रह।”\n\nउसी दिन सुन्दरदास अपनी पत्नी को लेने के लिए निकले। वे घोड़े पर सवार होकर वन के रास्ते से आ रहे थे। रास्ते में उन्हें प्यास लगी। वे एक वृक्ष के नीचे रुके और जल पीने लगे।\n\nउसी समय सत्यवती को माँ संतोषी की चेतावनी याद आई। वह घर में बैठी माँ संतोषी का नाम जप रही थी —\n\n“ॐ संतोषी मातायै नमः। जय संतोषी माता।”\n\nउधर वन में सुन्दरदास के समीप एक भयंकर साँप आया। वह उनकी ओर बढ़ने लगा। सुन्दरदास ने उसे देखा और भयभीत हो गए। उसी क्षण सत्यवती के जप का प्रभाव हुआ। साँप अपनी जगह पर स्तम्भित हो गया। उसे ऐसा लगा जैसे कोई अदृश्य शक्ति उसे रोक रही हो। वह सुन्दरदास को कुछ नहीं कर सका और पलटकर चला गया।\n\nसुन्दरदास ने ईश्वर को धन्यवाद दिया और घोड़े पर सवार होकर आगे बढ़े। जब वे अपने घर पहुँचे, तो सत्यवती ने उन्हें देखा और प्रसन्न हो गई। सुन्दरदास ने सारी घटना सुनाई —\n\n“सत्यवती! आज मुझे वन में एक भयंकर साँप मिला। वह मुझे डसने ही वाला था कि अचानक वह स्तम्भित हो गया और पलटकर चला गया। यह किसी दैवीय शक्ति का ही प्रभाव था।”\n\nसत्यवती मुस्कुराई और बोली —\n\n“स्वामी! यह माँ संतोषी की कृपा है। मैंने आपकी रक्षा के लिए उनका नाम जपा था।”\n\nसुन्दरदास ने सत्यवती की भक्ति को देखा और उनका हृदय गद्गद हो गया। उसने कहा —\n\n“सत्यवती! तू धन्य है। तेरी भक्ति से हमारा घर पवित्र हो गया है। अब मैं तुझे अपने घर ले जाने आया हूँ।”\n\nइस प्रकार सत्यवती अपने पति के साथ ससुराल लौट गई। माँ संतोषी की कृपा से उसका सुहाग अखण्ड रहा और वह सुखपूर्वक जीवन व्यतीत करने लगी।\n\nउसके बाद सत्यवती और सुन्दरदास ने मिलकर माँ संतोषी का मंदिर बनवाया और वहाँ प्रतिदिन पूजा-अर्चना होने लगी। सत्यवती ने अनेक स्त्रियों को इस व्रत का महात्म्य बताया और उन्हें माँ संतोषी की भक्ति में लगाया।\n\nएक दिन सत्यवती ने अपनी सास से पूछा —\n\n“माता! माँ संतोषी की कृपा से हमारा जीवन सुखी है। अब मैं जानना चाहती हूँ कि इस व्रत का सम्पूर्ण महात्म्य क्या है? जो स्त्री यह व्रत करती है, उसे क्या-क्या लाभ मिलते हैं?”\n\nसास ने कहा —\n\n“पुत्रि! मैं तो केवल इतना जानती हूँ कि यह व्रत 16 शुक्रवार तक किया जाता है और इससे सुख-शान्ति मिलती है। परन्तु माँ संतोषी स्वयं तुझे इसका सम्पूर्ण महात्म्य बताएँगी। तू उनसे प्रार्थना कर।”\n\nउसी रात सत्यवती ने माँ संतोषी से प्रार्थना की —\n\n“माँ! कृपया मुझे इस व्रत का सम्पूर्ण महात्म्य बताइए।”\n\nमाँ संतोषी ने स्वप्न में दर्शन दिए और कहा —\n\n“पुत्रि! कल प्रातः तू मंदिर में जाकर मेरी प्रतिमा के सम्मुख बैठना। मैं तुझे सम्पूर्ण महात्म्य बताऊँगी।”\n\nअगली प्रातः सत्यवती मंदिर में गई और प्रतिमा के सम्मुख बैठ गई। माँ संतोषी ने उसे दिव्य दर्शन दिए और व्रत का सम्पूर्ण महात्म्य, विधि और फल बताया। सत्यवती ने सब कुछ श्रद्धापूर्वक सुना और उसे सभी को बताया।\n\nइस प्रकार माँ संतोषी की कृपा से सत्यवती का जीवन धन्य हो गया और उसने अनेक जीवों को इस व्रत से लाभान्वित किया।";

    $ch4Title = "व्रत का महात्म्य, विधि एवं फलश्रुति";
    $ch4Story = "उस प्रातःकाल सत्यवती मंदिर में पहुँची। सूर्यदेव की पहली किरण मंदिर के शिखर पर पड़ रही थी और घंटियों की मधुर ध्वनि वातावरण में गूँज रही थी। सत्यवती ने माँ संतोषी की प्रतिमा के सम्मुख पुष्प अर्पित किए, दीपक जलाया और हाथ जोड़कर वहीं बैठ गई। उसके हृदय में एक ही प्रार्थना थी —\n\n“माँ! आपने मुझे इस व्रत से सुख-शान्ति दी। अब कृपया इस व्रत का सम्पूर्ण महात्म्य बताइए, जिससे मैं इसे और भी जीवों तक पहुँचा सकूँ।”\n\nतभी मंदिर में एक दिव्य प्रकाश फैल गया। प्रतिमा से एक अलौकिक तेज प्रकट हुआ और माँ संतोषी अपने दिव्य स्वरूप में सत्यवती के सम्मुख प्रकट हुईं। उनके चार हाथ थे, हाथों में वरद-मुद्रा और अभय-मुद्रा थी, मुकुट से रत्न चमक रहे थे और मुख पर वही सन्तोष की आभा थी जो सत्यवती ने पहली बार स्वप्न में देखी थी।\n\nसत्यवती ने दण्डवत प्रणाम किया —\n\n“माँ! मैं आपकी कृपा से धन्य हूँ। कृपया मुझे इस व्रत का सम्पूर्ण महात्म्य बताइए।”\n\nमाँ संतोषी ने मुस्कुराकर कहा —\n\n“पुत्रि! उठो। तुमने जो प्रश्न पूछा है, वही प्रश्न एक बार माता पार्वती ने भी भगवान शिव से पूछा था। सुनो, मैं तुम्हें इस व्रत का सम्पूर्ण महात्म्य विस्तार से बताती हूँ।”\n\nव्रत का प्रादुर्भाव\nमाँ संतोषी बोलीं —\n\n“पुत्रि! मैं साक्षात् श्रीगणेशजी की पुत्री हूँ। जब मेरे पिता ने देखा कि संसार के प्राणी सुख-सुविधा होने पर भी असंतोष से ग्रस्त हैं, तब उन्होंने अपनी दिव्य शक्ति से मुझे प्रकट किया। मेरा नाम ‘संतोषी’ रखा गया, क्योंकि मैं अपने भक्तों के हृदय में सन्तोष भर देती हूँ। जिसके हृदय में सन्तोष है, उसके पास सब कुछ है; और जिसके हृदय में असंतोष है, उसके पास कुछ भी नहीं।”\n\nसत्यवती ने पूछा —\n\n“माँ! इस व्रत के लिए शुक्रवार का दिन क्यों चुना गया?”\n\nमाँ संतोषी ने कहा —\n\n“पुत्रि! शुक्रवार का दिन शुक्राचार्य का दिन है, जो समृद्धि और सौभाग्य के देवता हैं। यह दिन माँ लक्ष्मी को भी प्रिय है। जो स्त्री शुक्रवार को मेरा व्रत करती है, उसके घर में लक्ष्मी का वास होता है और समृद्धि बनी रहती है। इसलिए शुक्रवार मेरे व्रत का सर्वश्रेष्ठ दिन है।”\n\nसत्यवती ने पूछा —\n\n“माँ! यह व्रत सोलह शुक्रवार तक ही क्यों किया जाता है? सोलह का क्या महात्म्य है?”\n\nमाँ संतोषी ने कहा —\n\n“पुत्रि! सोलह का अर्थ है — पूर्णता। चन्द्रमा की सोलह कलाएँ होती हैं। सोलह संस्कार हैं। सोलह दिनों तक व्रत करने से भक्त का संकल्प दृढ़ हो जाता है और उसका हृदय शुद्ध हो जाता है। जो सोलह शुक्रवार तक मेरा व्रत करता है, उसके जीवन की सोलह कलाएँ पूर्ण हो जाती हैं।”\n\nव्रत की विधि\nसत्यवती ने हाथ जोड़कर पूछा —\n\n“माँ! कृपया मुझे इस व्रत की सम्पूर्ण विधि बताइए।”\n\nमाँ संतोषी ने कहा —\n\n“पुत्रि! सुनो, व्रत की विधि इस प्रकार है —\n\n1. संकल्प: प्रातः ब्रह्ममुहूर्त में स्नान करके स्वच्छ वस्त्र पहनो। मेरी प्रतिमा या चित्र के सम्मुख बैठकर हाथ में जल और अक्षत लेकर संकल्प करो कि ‘मैं अपने परिवार के सुख, शान्ति और समृद्धि के लिए सोलह शुक्रवार का व्रत करूँगी।’\n\n2. व्रत का पालन: व्रत के दिन फलाहार कर सकती हो या निराहार रह सकती हो — दोनों विधियाँ शास्त्र-सम्मत हैं। परन्तु जो भी करो, श्रद्धा से करो। अस्वस्थता में शास्त्र और चिकित्सक के परामर्श का पालन करो।\n\n3. खट्टी वस्तुओं का त्याग: व्रत के दिन और पारण में खट्टी वस्तुएँ — दही, इमली, नींबू, अमचूर, सिरका आदि — ग्रहण न करो। क्योंकि खट्टापन असंतोष का प्रतीक है। जो असंतोष को त्यागता है, वही सन्तोष को प्राप्त करता है। यह इस व्रत का सबसे महत्वपूर्ण नियम है।\n\n4. पूजन: सायंकाल मेरी प्रतिमा और श्रीगणेशजी का विधिवत पूजन करो। रोली से स्वस्तिक बनाओ, अक्षत अर्पित करो, पुष्प चढ़ाओ, धूप-दीप जलाओ। मुझे गुड़ और चने की दाल का भोग अवश्य लगाओ — यह मेरा प्रिय नैवेद्य है। केला, नारियल और मिष्ठान भी अर्पित कर सकती हो।\n\n5. कथा श्रवण: प्रत्येक शुक्रवार को मेरी कथा श्रद्धापूर्वक सुनो या पढ़ो। कथा सुनने से व्रत का फल दुगुना हो जाता है।\n\n6. प्रसाद वितरण: भोग लगाने के बाद प्रसाद ग्रहण करो और दूसरों को भी बाँटो। जो प्रसाद बाँटता है, उसका पुण्य बढ़ता है।\n\n7. उद्यापन: सोलहवें शुक्रवार को उद्यापन करो। इस दिन विशेष पूजन करो, गुड़-चने का भोग लगाओ, कथा सुनो और प्रसाद बाँटो। उद्यापन के दिन किसी ब्राह्मण, साधु या जरूरतमंद को भोजन अवश्य कराओ।”\n\nव्रत के नियम\nसत्यवती ने पूछा —\n\n“माँ! इस व्रत में किन नियमों का पालन करना चाहिए?”\n\nमाँ संतोषी ने कहा —\n\n“पुत्रि! सुनो —\n\nव्रत के दिन सत्य बोलो, किसी की निन्दा मत करो, क्रोध मत करो।\nघर में शान्ति रखो। कलह से व्रत का फल नष्ट हो जाता है।\nव्रत के दिन दान अवश्य करो — अन्न, वस्त्र या धन, जो भी सम्भव हो।\nव्रत का संकल्प एक बार लेने के बाद उसे पूर्ण करो। बीच में मत छोड़ो।\nयदि किसी कारण से कोई शुक्रवार छूट जाए, तो अगले शुक्रवार को दो व्रत करके उसकी पूर्ति करो।\nव्रत के दिन किसी का अपमान मत करो। जो अपमान करता है, उसका व्रत निष्फल हो जाता है।”\n\nसत्यवती ने पूछा —\n\n“माँ! क्या पुरुष भी यह व्रत कर सकते हैं?”\n\nमाँ संतोषी ने मुस्कुराकर कहा —\n\n“पुत्रि! यह व्रत मुख्यतः स्त्रियों के लिए है, परन्तु जो पुरुष श्रद्धा से यह व्रत करता है, उसे भी मेरी कृपा प्राप्त होती है। मेरी कृपा किसी जाति, लिंग या वर्ण का भेद नहीं करती। जो भक्त है, वह मेरा है।”\n\nव्रत का फल\nसत्यवती ने पूछा —\n\n“माँ! इस व्रत से कौन-कौन से फल प्राप्त होते हैं?”\n\nमाँ संतोषी ने कहा —\n\n“पुत्रि! सुनो, जो भक्त श्रद्धा और भक्ति से यह व्रत करता है —\nउसके जीवन से असंतोष दूर हो जाता है और सन्तोष की प्राप्ति होती है।\nघर में सुख, शान्ति और समृद्धि आती है।\nधन-धान्य की वृद्धि होती है।\nसंतान-सुख की प्राप्ति होती है।\nकन्या के विवाह में आने वाली बाधाएँ दूर होती हैं।\nपति-पत्नी में प्रेम और विश्वास बढ़ता है।\nरोग और शोक दूर होते हैं।\nजो स्त्री यह व्रत करती है, उसका सौभाग्य अखण्ड रहता है।\nजो कन्या यह व्रत करती है, उसे मनोवांछित वर की प्राप्ति होती है।\nजो व्यापारी यह व्रत करता है, उसके व्यापार में वृद्धि होती है।\nजो विद्यार्थी यह व्रत करता है, उसकी बुद्धि तीव्र होती है।\nजो स्त्री सन्तान की प्राप्ति के लिए यह व्रत करती है, उसे संतान-सुख मिलता है।\n\nपरन्तु पुत्रि, सबसे बड़ा फल यह है कि जो मेरा व्रत करता है, उसके हृदय में सन्तोष का वास हो जाता है। और जिसके हृदय में सन्तोष है, उसके लिए यह सारा संसार ही स्वर्ग है।”\n\nभक्ति का महात्म्य\nसत्यवती ने पूछा —\n\n“माँ! आपने मेरी परीक्षा ली थी। मेरी ननदों ने मेरे प्रसाद को खा लिया था और मुझ पर झूठा आरोप लगाया था। तब आपने मेरी रक्षा कैसे की?”\n\nमाँ संतोषी ने कहा —\n\n“पुत्रि! जो मेरा भक्त है, उसकी रक्षा मैं स्वयं करती हूँ। तुम्हारी ननदों ने तुम्हारा प्रसाद खाया, परन्तु तुम्हारा संकल्प नहीं खाया जा सका। तुम्हारा हृदय शुद्ध था, इसलिए मैंने तुम्हारी रक्षा की। जो भक्त निर्दोष है, उसे मैं कभी नहीं छोड़ती।”\n\nसत्यवती की आँखों में आँसू थे। उसने हाथ जोड़कर कहा —\n\n“माँ! आपने मुझे सब कुछ दिया। अब मैं क्या करूँ?”\n\nमाँ संतोषी ने कहा —\n\n“पुत्रि! अब तुम इस व्रत का महात्म्य सभी को बताओ। जो इस कथा को सुनकर व्रत करेगा, उसे मेरी कृपा प्राप्त होगी। यही मेरी सच्ची पूजा है।”\n\nफलश्रुति\nमाँ संतोषी ने कहा —\n\n“पुत्रि! जो व्यक्ति इस संतोषी माता व्रत कथा को श्रद्धापूर्वक सुनता है, वह इस व्रत का सम्पूर्ण फल प्राप्त करता है। जो स्त्री इस कथा को सुनकर सोलह शुक्रवार का व्रत करती है, उसका जीवन सुखमय हो जाता है और अन्त में उसे मेरे लोक की प्राप्ति होती है। जो कन्या इस कथा को सुनती है, उसे योग्य वर मिलता है। जो पुरुष इस कथा को सुनता है, उसके जीवन से असंतोष दूर हो जाता है।\n\nजो इस कथा को पढ़ता या सुनाता है, उसके हृदय में सन्तोष का वास होता है। यह कथा जिस घर में सुनी जाती है, वहाँ सुख, समृद्धि और शान्ति बनी रहती है।”\n\nइसके बाद माँ संतोषी ने सत्यवती को आशीर्वाद दिया —\n\n“पुत्रि! तुम्हारा सुहाग अखण्ड रहे, तुम्हारे घर में सदा सन्तोष का वास हो, तुम्हारी सन्तान सुखी और यशस्वी हो। जो तुम्हारी भाँति मेरी शरण में आए, उसकी मैं सदा रक्षा करूँगी।”\n\nसत्यवती ने माँ संतोषी के चरणों में अपना सिर रख दिया और रो पड़ी —\n\n“माँ! मैं आपकी ऋणी हूँ। आपने मुझे जीवन दिया।”\n\nमाँ संतोषी ने उसे उठाया और अन्तर्धान हो गईं।\n\nउसके बाद सत्यवती ने अपना शेष जीवन माँ संतोषी की भक्ति में लगा दिया। उसने मंदिर बनवाया, व्रत का प्रचार किया और अनेक स्त्रियों को इस व्रत से लाभान्वित किया। माँ संतोषी की कृपा से उसका परिवार सदा सुखी रहा।\n\nइति श्री संतोषी माता व्रत कथा सम्पूर्णम्।\n\nॐ संतोषी मातायै नमः।\nया देवी सर्वभूतेषु सन्तोषरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥";

