    $idsToUpsert = [
        'santoshi_mata_vrat_katha',
        'katha_santoshi_mata'
    ];

    $affected = 0;

    $sql = "INSERT INTO `vrat_katha` (
        `id`, `title`, `katha_name`, `sanskrit_title`, `sanskrit`, `category`, `category_label`,
        `deity`, `deity_name`, `duration`, `vrat_duration`, `vrat_day`, `vrat_month`, `tithi`,
        `synopsis`, `vrat_significance`, `benefits`, `rules`, `opening_verse`, `closing_verse`,
        `aarti_name`, `samagri_list`, `vidhi`, `katha_chapters`, `chapters`, `katha_text`,
        `translation_hi`, `translation_en`, `translation_gu`, `translation_mr`, `is_featured`
    ) VALUES (
        :id, :title, :katha_name, :sanskrit_title, :sanskrit, :category, :category_label,
        :deity, :deity_name, :duration, :vrat_duration, :vrat_day, :vrat_month, :tithi,
        :synopsis, :vrat_significance, :benefits, :rules, :opening_verse, :closing_verse,
        :aarti_name, :samagri_list, :vidhi, :katha_chapters, :chapters, :katha_text,
        :translation_hi, :translation_en, :translation_gu, :translation_mr, :is_featured
    ) ON DUPLICATE KEY UPDATE
        `title` = VALUES(`title`),
        `katha_name` = VALUES(`katha_name`),
        `sanskrit_title` = VALUES(`sanskrit_title`),
        `sanskrit` = VALUES(`sanskrit`),
        `category` = VALUES(`category`),
        `category_label` = VALUES(`category_label`),
        `deity` = VALUES(`deity`),
        `deity_name` = VALUES(`deity_name`),
        `duration` = VALUES(`duration`),
        `vrat_duration` = VALUES(`vrat_duration`),
        `vrat_day` = VALUES(`vrat_day`),
        `vrat_month` = VALUES(`vrat_month`),
        `tithi` = VALUES(`tithi`),
        `synopsis` = VALUES(`synopsis`),
        `vrat_significance` = VALUES(`vrat_significance`),
        `benefits` = VALUES(`benefits`),
        `rules` = VALUES(`rules`),
        `opening_verse` = VALUES(`opening_verse`),
        `closing_verse` = VALUES(`closing_verse`),
        `aarti_name` = VALUES(`aarti_name`),
        `samagri_list` = VALUES(`samagri_list`),
        `vidhi` = VALUES(`vidhi`),
        `katha_chapters` = VALUES(`katha_chapters`),
        `chapters` = VALUES(`chapters`),
        `katha_text` = VALUES(`katha_text`),
        `translation_hi` = VALUES(`translation_hi`),
        `translation_en` = VALUES(`translation_en`),
        `translation_gu` = VALUES(`translation_gu`),
        `translation_mr` = VALUES(`translation_mr`),
        `is_featured` = VALUES(`is_featured`)";

    $stmt = $db->prepare($sql);

    foreach ($idsToUpsert as $kId) {
        $params = array_merge($kathaData, [':id' => $kId]);
        $execParams = [];
        foreach ($params as $k => $v) {
            $key = str_starts_with($k, ':') ? $k : (':' . $k);
            $execParams[$key] = $v;
        }
        $stmt->execute($execParams);
        $affected++;
    }

    // Refresh vrat_kathas view
    try {
        $db->exec("CREATE OR REPLACE VIEW `vrat_kathas` AS SELECT * FROM `vrat_katha`");
    } catch (Exception $e) {}

    // Invalidate local filesystem caches
    $cacheDir = $webBackend . '/cache';
    if (is_dir($cacheDir)) {
        foreach (glob($cacheDir . '/*.json') as $cacheFile) {
            @unlink($cacheFile);
        }
    }

    $response = [
        "status" => "success",
        "message" => "Santoshi Mata Vrat Katha successfully updated with all 4 comprehensive chapters in MySQL.",
        "upserted_ids" => $idsToUpsert,
        "total_chapters" => 4,
        "katha_text_length" => mb_strlen($kathaFullText, 'UTF-8'),
        "timestamp" => date('c')
    ];

    if ($isCli) {
        echo json_encode($response, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE) . "\n";
    } else {
        header("Content-Type: application/json; charset=UTF-8");
        echo json_encode($response, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE);
    }

} catch (Throwable $e) {
    $errResp = [
        "status" => "error",
        "message" => $e->getMessage(),
        "trace" => $e->getTraceAsString()
    ];
    if ($isCli) {
        fwrite(STDERR, json_encode($errResp, JSON_PRETTY_PRINT) . "\n");
        exit(1);
    } else {
        header("Content-Type: application/json; charset=UTF-8");
        http_response_code(500);
        echo json_encode($errResp, JSON_PRETTY_PRINT);
    }
